'use strict';

const fs = require('node:fs');
const path = require('node:path');
const {
  normalizeEmail,
  selectLeads,
  buildPrompt,
  parseDraft,
  claimUpdate,
  doneUpdate,
  failUpdate,
} = require('../src/followup');

function toLf(str) {
  return String(str).replace(/\r\n/g, '\n');
}

function buildSelectLeadsSnippet(eol = '\n') {
  const lines = [
    '// Generated by scripts/build-snippets.js from src/followup.js — do not edit by hand.',
    '// n8n Code node ("Select leads") — Mode: Run Once for All Items',
    '',
    toLf(normalizeEmail.toString()),
    '',
    toLf(selectLeads.toString()),
    '',
    toLf(buildPrompt.toString()),
    '',
    toLf(claimUpdate.toString()),
    '',
    'const rows = $input.all().map(i => i.json);',
    'let config = {};',
    'try {',
    "  config = $('Config').first().json || {};",
    '} catch (_err) {',
    '  config = {};',
    '}',
    '',
    'const nowMs = Date.now();',
    'const nowIso = new Date(nowMs).toISOString();',
    'const runId =',
    "  typeof $execution !== 'undefined' && $execution && $execution.id",
    '    ? String($execution.id)',
    '    : `run-${nowMs}`;',
    '',
    'const { toDraft, stuck } = selectLeads(rows, {',
    '  nowMs,',
    '  staleMinutes: Number(config.staleMinutes ?? 30),',
    '  maxPerRun: Number(config.maxPerRun ?? 10),',
    '});',
    '',
    'const out = [];',
    '',
    'for (const lead of toDraft) {',
    '  const claim = claimUpdate(lead, runId, nowIso);',
    '  const prompt = buildPrompt(lead, {',
    "    senderName: config.senderName || 'Sender',",
    "    offer: config.offer || '',",
    '  });',
    '  out.push({',
    '    json: {',
    '      ...lead,',
    '      ...claim,',
    '      prompt,',
    "      _route: 'draft',",
    '    },',
    '  });',
    '}',
    '',
    'for (const lead of stuck) {',
    '  out.push({',
    '    json: {',
    '      ...lead,',
    "      _route: 'stuck',",
    '    },',
    '  });',
    '}',
    '',
    'return out;',
    '',
  ];

  return lines.join('\n').replace(/\n/g, eol);
}

function buildParseDraftSnippet(eol = '\n') {
  const lines = [
    '// Generated by scripts/build-snippets.js from src/followup.js — do not edit by hand.',
    '// n8n Code node ("Parse draft") — Mode: Run Once for Each Item',
    '',
    toLf(parseDraft.toString()),
    '',
    toLf(doneUpdate.toString()),
    '',
    toLf(failUpdate.toString()),
    '',
    'const itemJson = $input.item.json || {};',
    'let lead = itemJson;',
    'try {',
    "  lead = { ...$('Select leads').item.json, ...itemJson };",
    '} catch (_err) {',
    '  lead = itemJson;',
    '}',
    '',
    'const llmText =',
    "  typeof itemJson.text === 'string'",
    '    ? itemJson.text',
    "    : typeof itemJson.response === 'string'",
    '      ? itemJson.response',
    "      : typeof itemJson.output === 'string'",
    '        ? itemJson.output',
    "        : '';",
    '',
    'const parsed = parseDraft(llmText);',
    '',
    'if (parsed.ok) {',
    '  return {',
    '    json: {',
    '      ...lead,',
    '      ok: true,',
    '      subject: parsed.subject,',
    '      body: parsed.body,',
    "      error: '',",
    '    },',
    '  };',
    '}',
    '',
    'const failure = failUpdate(lead, parsed.error);',
    'return {',
    '  json: {',
    '    ...lead,',
    '    ...failure,',
    '    ok: false,',
    "    subject: '',",
    "    body: '',",
    '    error: parsed.error,',
    '  },',
    '};',
    '',
  ];

  return lines.join('\n').replace(/\n/g, eol);
}

function buildSnippets(eol = '\n') {
  return {
    'select-leads.js': buildSelectLeadsSnippet(eol),
    'parse-draft.js': buildParseDraftSnippet(eol),
  };
}

function writeSnippets() {
  const snippetsDir = path.join(__dirname, '..', 'snippets');
  fs.mkdirSync(snippetsDir, { recursive: true });
  const files = buildSnippets('\n');
  for (const [name, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(snippetsDir, name), content, 'utf8');
  }
}

// Keep the Code nodes inside the importable workflow identical to the snippets.
const WORKFLOW_CODE_NODES = { 'Select leads': 'select-leads.js', 'Parse draft': 'parse-draft.js' };

function writeWorkflowCode() {
  const workflowPath = path.join(__dirname, '..', 'workflows', 'lead-followup-drafts.json');
  const workflow = JSON.parse(fs.readFileSync(workflowPath, 'utf8'));
  const files = buildSnippets('\n');
  for (const node of workflow.nodes) {
    const file = WORKFLOW_CODE_NODES[node.name];
    if (file) node.parameters.jsCode = files[file];
  }
  fs.writeFileSync(workflowPath, JSON.stringify(workflow, null, 2) + '\n', 'utf8');
}

if (require.main === module) {
  writeSnippets();
  writeWorkflowCode();
}

module.exports = {
  buildSelectLeadsSnippet,
  buildParseDraftSnippet,
  buildSnippets,
  writeSnippets,
  writeWorkflowCode,
  WORKFLOW_CODE_NODES,
};
